"""Framing, authentication, ASCII armor, and chunked payload handling."""
import base64
import hashlib
import hmac
import os
from .errors import AgeError, quote
from .primitives import b64encode, b64decode, DecodeError, hkdf, seal, unseal

INTRO = b'age-encryption.org/v1\n'
ARMOR_START = b'-----BEGIN AGE ENCRYPTED FILE-----'
ARMOR_END = b'-----END AGE ENCRYPTED FILE-----'
CHUNK = 65536
AUTH_ERROR = 'failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with'


class InputBuffer:
    """A byte stream with a deferred read failure (for layered armor errors)."""
    def __init__(self, data, error=None):
        self.data = data
        self.offset = 0
        self.error = error

    def read(self, n=-1):
        if n < 0:
            n = len(self.data) - self.offset
        out = self.data[self.offset:self.offset+n]
        self.offset += len(out)
        return out

    def readline(self):
        end = self.data.find(b'\n', self.offset)
        if end == -1:
            self.offset = len(self.data)
            raise AgeError(self.error or 'EOF')
        out = self.data[self.offset:end+1]
        self.offset = end+1
        return out

    def peek(self, count):
        out = self.data[self.offset:self.offset+count]
        if len(out) < count:
            raise AgeError(self.error or 'EOF')
        return out


def dearmor(data, error=None):
    # Leading ASCII whitespace is considered for auto-detection, not stripped
    # from the actual first nonempty armor line.
    if not data.lstrip(b' \t\r\n').startswith(ARMOR_START):
        return InputBuffer(data, error)
    result = bytearray()
    lines = data.split(b'\n')
    index = 0
    def next_line():
        nonlocal index
        if index >= len(lines):
            raise AgeError('invalid armor: unexpected EOF')
        line = lines[index]
        index += 1
        if index == len(lines) and not line:
            raise AgeError('invalid armor: unexpected EOF')
        return line[:-1] if line.endswith(b'\r') else line
    try:
        first = next_line()
        while first == b'':
            first = next_line()
        if first != ARMOR_START:
            raise AgeError('invalid armor: invalid first line: ' + quote(first))
        short = False
        while True:
            line = next_line()
            if line == ARMOR_END:
                rest = b'\n'.join(lines[index:])
                if rest.strip(b' \r\n\t'):
                    raise AgeError('invalid armor: trailing data after armored file')
                return InputBuffer(bytes(result), error)
            if short:
                raise AgeError('invalid armor: invalid closing line: ' + quote(line))
            if len(line) > 64:
                raise AgeError('invalid armor: column limit exceeded')
            try:
                block = b64decode(line, padded=True)
            except DecodeError as e:
                raise AgeError('invalid armor: ' + str(e))
            result.extend(block)
            short = len(line) < 64 or line.endswith(b'=')
    except AgeError as e:
        return InputBuffer(bytes(result), str(e))


def armor(data):
    encoded = base64.b64encode(data)
    return ARMOR_START+b'\n'+b'\n'.join(encoded[i:i+64] for i in range(0,len(encoded),64))+b'\n'+ARMOR_END+b'\n'


def parse_header(stream):
    try:
        line = stream.readline()
    except AgeError as e:
        if str(e) == 'EOF':
            raise AgeError('failed to read header: parsing age header: file is empty')
        raise AgeError('failed to read header: parsing age header: failed to read intro: '+str(e))
    if line != INTRO:
        if line == b'age-encryption.org/v1\r\n' or line.startswith(b'\xff\xfea\0g\0e\0'):
            raise AgeError('invalid header intro', ('it looks like this file was corrupted by PowerShell redirection', 'consider using -o or -a to encrypt files in PowerShell'))
        raise AgeError('failed to read header: parsing age header: unexpected intro: '+quote(line))
    stanzas = []
    header = bytearray(INTRO)
    first = True
    while True:
        try:
            peek = stream.peek(3)
        except AgeError as e:
            prefix = 'parsing age header: ' if first else ''
            raise AgeError('failed to read header: '+prefix+'failed to read header: '+str(e))
        first = False
        if peek == b'---':
            try:
                line = stream.readline()
            except AgeError as e:
                raise AgeError('failed to read header: failed to read header: '+str(e))
            fields = line[:-1].split(b' ')
            if len(fields) != 2 or fields[0] != b'---':
                raise AgeError('failed to read header: parsing age header: malformed closing line: '+quote(line))
            why = '<nil>'
            try:
                mac = b64decode(fields[1])
            except DecodeError as e:
                mac = b''
                why = str(e)
            if len(mac) != 32:
                raise AgeError('failed to read header: parsing age header: malformed closing line '+quote(line)+': '+why)
            header.extend(b'---')
            return stanzas, mac, bytes(header), stream
        try:
            line = stream.readline()
        except AgeError as e:
            raise AgeError('failed to read header: failed to parse header: failed to read line: '+str(e))
        if not line.startswith(b'->'):
            raise AgeError('failed to read header: failed to parse header: malformed stanza opening line: '+quote(line))
        fields = line[:-1].split(b' ')
        if len(fields)<2 or fields[0]!=b'->' or any(not x or any(c<33 or c>126 for c in x) for x in fields[1:]):
            raise AgeError('failed to read header: failed to parse header: malformed stanza: '+quote(line))
        header.extend(line)
        body = bytearray()
        while True:
            try:
                line = stream.readline()
            except AgeError as e:
                raise AgeError('failed to read header: failed to parse header: failed to read line: '+str(e))
            if line.startswith((b'->', b'---')):
                raise AgeError('failed to read header: failed to parse header: malformed body line '+quote(line)+': stanza ended without a short line\nnote: this might be a file encrypted with an old beta version of age or rage; use age v1.0.0-beta6 or rage to decrypt it')
            try:
                decoded = b64decode(line[:-1])
                if len(decoded)>48:
                    raise DecodeError('line too long')
            except DecodeError as e:
                raise AgeError('failed to read header: failed to parse header: parsing age header: malformed body line '+quote(line)+': '+str(e))
            header.extend(line)
            body.extend(decoded)
            if len(decoded)<48:
                break
        stanzas.append((fields[1].decode('ascii'), [x.decode('ascii') for x in fields[2:]], bytes(body)))


def encode_stanza(kind, args, body):
    opening = '-> ' + kind
    if args:
        opening += ' ' + ' '.join(args)
    encoded = b64encode(body)
    lines = [encoded[i:i+64] for i in range(0, len(encoded), 64)]
    if not encoded or len(encoded)%64 == 0:
        lines.append(b'')
    return opening.encode('ascii')+b'\n'+b'\n'.join(lines)+b'\n'


def make_header(stanzas, key):
    header = INTRO+b''.join(encode_stanza(*s) for s in stanzas)+b'---'
    mac = hmac.digest(hkdf(key, info=b'header'), header, 'sha256')
    return header+b' '+b64encode(mac)+b'\n'


def check_header(key, mac, header):
    expected = hmac.digest(hkdf(key, info=b'header'), header, 'sha256')
    if not hmac.compare_digest(expected, mac):
        raise AgeError('bad header MAC')


def encrypt_payload(key, data):
    salt = os.urandom(16)
    cipherkey = hkdf(key, salt, b'payload')
    out = bytearray(salt)
    for i in range(max(1, (len(data)+CHUNK-1)//CHUNK)):
        part = data[i*CHUNK:(i+1)*CHUNK]
        final = (i+1)*CHUNK >= len(data)
        nonce = i.to_bytes(11,'big')+bytes([final])
        out.extend(seal(cipherkey, part, nonce))
    return bytes(out)


def decrypt_payload(key, stream, write):
    salt = stream.read(16)
    if len(salt)<16:
        raise AgeError('failed to read nonce: '+(stream.error or ('unexpected EOF' if salt else 'EOF')))
    cipherkey = hkdf(key, salt, b'payload')
    counter = 0
    while True:
        chunk = stream.read(CHUNK+16)
        # A deferred source error is returned instead of authenticating a short
        # chunk, just like a read-full based streaming reader.
        if len(chunk)<CHUNK+16 and stream.error:
            raise AgeError(stream.error)
        at_end = stream.offset == len(stream.data)
        if not chunk:
            raise AgeError('unexpected EOF')
        nonce = counter.to_bytes(11,'big')+bytes([at_end])
        plain = unseal(cipherkey, chunk, nonce)
        if plain is None:
            raise AgeError(AUTH_ERROR)
        write(plain)
        if at_end:
            return
        counter += 1
