cat > ageclone/terminal.py <<'PY'
import os
import sys
import termios
from .errors import AgeError, os_error, quote


def read_secret(prompt):
    own = False
    try:
        if os.isatty(0):
            fd = 0
        else:
            try:
                fd = os.open('/dev/tty', os.O_RDWR)
                own = True
            except OSError as e:
                raise AgeError('could not read passphrase: standard input is not a terminal, and /dev/tty is not available: '+os_error(e,'open','/dev/tty'))
        outfd = fd if own else 2
        os.write(outfd, prompt.encode())
        attrs = termios.tcgetattr(fd)
        new = list(attrs)
        new[3] &= ~termios.ECHO
        termios.tcsetattr(fd, termios.TCSAFLUSH, new)
        try:
            buf = bytearray()
            while True:
                part = os.read(fd, 1)
                if not part:
                    raise AgeError('could not read passphrase: EOF')
                if part in (b'\r',b'\n'):
                    break
                if part == b'\x03':
                    raise AgeError('could not read passphrase: interrupted')
                buf.extend(part)
        finally:
            termios.tcsetattr(fd, termios.TCSAFLUSH, attrs)
            os.write(outfd,b'\r\n\x1b[F\x1b[K')
        return bytes(buf)
    finally:
        if own:
            os.close(fd)


def encryption_passphrase():
    value = read_secret('Enter passphrase (leave empty to autogenerate a secure one): ')
    if not value:
        # A CSPRNG-generated passphrase; the exact generated value is of course
        # intentionally not reproducible between executions.
        alphabet = 'abcdefghijklmnopqrstuvwxyz'
        words = []
        for i in range(10):
            words.append(''.join(alphabet[b%26] for b in os.urandom(6)))
        value = '-'.join(words).encode()
        sys.stderr.write('age: using autogenerated passphrase '+quote(value)+'\n')
        return value
    confirmation = read_secret('Confirm passphrase: ')
    if value != confirmation:
        raise AgeError("passphrases didn't match")
    return value
