"""Native recipients and identities, and user-specified key files."""
import hashlib
import os
import re
import sys
from .errors import AgeError, quote, os_error
from .primitives import bech_decode, bech_encode, b64encode, b64decode, hkdf, x25519, seal, unseal, DecodeError
from . import format as framing
from .terminal import read_secret

DOMAIN = b'age-encryption.org/v1/'


class XKey:
    pq = False
    def __init__(self, public=None, secret=None):
        self.secret = secret
        self.public = public if public is not None else x25519(secret)

    def wrap(self, key):
        ephemeral = os.urandom(32)
        ephemeral_pub = x25519(ephemeral)
        shared = x25519(ephemeral, self.public)
        if shared == bytes(32):
            raise AgeError('failed to encrypt to X25519 recipient: crypto/ecdh: bad X25519 remote ECDH input: low order point')
        wrapkey = hkdf(shared, ephemeral_pub+self.public, DOMAIN+b'X25519')
        return [('X25519', [b64encode(ephemeral_pub).decode()], seal(wrapkey, key))]

    def unwrap(self, stanzas):
        for kind, args, body in stanzas:
            if kind != 'X25519':
                continue
            if len(args) != 1:
                raise AgeError('invalid X25519 recipient block')
            try:
                ephemeral = b64decode(args[0])
            except DecodeError as e:
                raise AgeError('failed to parse X25519 recipient: '+str(e))
            if len(ephemeral)!=32:
                raise AgeError('invalid X25519 recipient: invalid public key size')
            shared = x25519(self.secret, ephemeral)
            if shared == bytes(32):
                raise AgeError('invalid X25519 recipient: crypto/ecdh: bad X25519 remote ECDH input: low order point')
            wrapkey = hkdf(shared, ephemeral+self.public, DOMAIN+b'X25519')
            key = unseal(wrapkey, body)
            if key is not None:
                if len(key)!=16:
                    raise AgeError('invalid X25519 recipient block')
                return key
        return None


class PluginKey:
    pq = None
    def __init__(self, name, recipient=None, identity=None):
        if not name or re.fullmatch(r'[a-zA-Z0-9_.-]+', name) is None:
            raise AgeError('invalid plugin name: '+quote(name))
        self.name, self.recipient, self.identity = name, recipient, identity

    def _fail(self):
        message = self.name+' plugin: couldn\'t start plugin: '+quote(self.name)+' plugin not found: exec: '+quote('age-plugin-'+self.name)+': executable file not found in $PATH'
        raise AgeError(message, ('you might want to install the '+quote(self.name)+' plugin', 'visit https://age-encryption.org/awesome#plugins for a list of available plugins'))

    def wrap(self, key):
        self._fail()

    def unwrap(self, stanzas):
        self._fail()


class PassphraseKey:
    pq = True
    def __init__(self, passphrase=None):
        self.passphrase = passphrase

    def wrap(self, key):
        salt = os.urandom(16)
        wk = hashlib.scrypt(self.passphrase, salt=DOMAIN+b'scrypt'+salt, n=1<<18, r=8, p=1, maxmem=2147483646, dklen=32)
        return [('scrypt',[b64encode(salt).decode(),'18'],seal(wk,key))]

    def unwrap(self, stanzas):
        if len(stanzas)!=1 or stanzas[0][0]!='scrypt':
            return None
        kind,args,body = stanzas[0]
        if self.passphrase is None:
            try:
                self.passphrase = read_secret('Enter passphrase: ')
            except AgeError as e:
                raise AgeError('could not read passphrase: '+str(e))
        if len(args)!=2:
            raise AgeError('invalid scrypt recipient block')
        try:
            salt = b64decode(args[0])
        except DecodeError as e:
            raise AgeError('failed to parse scrypt salt: '+str(e))
        if len(salt)!=16:
            raise AgeError('invalid scrypt salt')
        if not re.fullmatch(r'[1-9][0-9]*',args[1]):
            raise AgeError('invalid scrypt work factor')
        work = int(args[1])
        if work>30:
            raise AgeError('scrypt work factor too large')
        wk = hashlib.scrypt(self.passphrase, salt=DOMAIN+b'scrypt'+salt, n=1<<work, r=8, p=1, maxmem=2147483646, dklen=32)
        key = unseal(wk,body)
        if key is None:
            raise AgeError('incorrect passphrase')
        if len(key)!=16:
            raise AgeError('invalid scrypt recipient block')
        return key


def is_passphrase(stanzas):
    return any(kind=='scrypt' for kind,args,body in stanzas)


def find_key(identities, stanzas):
    for identity in identities:
        key = identity.unwrap(stanzas)
        if key is not None:
            return key
    raise AgeError('no identity matched any of the recipients')


class EncryptedIdentity:
    pq = None
    def __init__(self, data, name):
        self.data, self.name = data, name
        self.identities = None

    def load(self):
        if self.identities is None:
            try:
                s,m,h,stream = framing.parse_header(framing.dearmor(self.data))
                if not is_passphrase(s):
                    raise AgeError('identity file is not passphrase-encrypted')
                try:
                    password = read_secret('Enter passphrase for identity file '+quote(self.name)+': ')
                except AgeError as e:
                    raise AgeError('could not read passphrase: '+str(e))
                key = PassphraseKey(password).unwrap(s)
                framing.check_header(key,m,h)
                out = []
                framing.decrypt_payload(key,stream,out.append)
                self.identities = parse_identity_lines(b''.join(out),self.name)
            except AgeError as e:
                raise AgeError('failed to decrypt identity file: '+str(e),e.hints)
        return self.identities

    def unwrap(self, stanzas):
        for identity in self.load():
            key = identity.unwrap(stanzas)
            if key is not None:
                return key
        return None

    def wrap(self, key):
        stanzas = []
        for identity in self.load():
            stanzas.extend(identity.wrap(key))
        return stanzas


def parse_recipient(text):
    if text.startswith('age1'):
        # Native types are selected by their full HRP; the remaining HRPs name
        # extensions, each of which carries opaque bytes in the same encoding.
        plugin = '1' in text[4:] and not text.startswith(('age1pq1','age1tag1','age1tagpq1'))
        try:
            hrp, data = bech_decode(text)
        except DecodeError as e:
            if plugin:
                raise AgeError('invalid recipient encoding: '+str(e))
            extra = 'invalid recipient encoding: ' if text.startswith(('age1tag1','age1tagpq1')) else ''
            raise AgeError('malformed recipient '+quote(text)+': '+extra+str(e))
        if hrp == 'age':
            if len(data)!=32:
                raise AgeError('malformed recipient '+quote(text)+': invalid X25519 public key')
            return XKey(public=data)
        if hrp == 'age1pq':
            if len(data)!=1216:
                raise AgeError('malformed recipient '+quote(text)+': invalid MLKEM768-X25519 public key')
            from .pq import PQKey
            return PQKey(public=data)
        if hrp == 'age1tag':
            if len(data)!=33:
                raise AgeError('malformed recipient '+quote(text)+': invalid tag recipient public key size '+str(len(data)))
            from .tag import TagKey
            try:
                return TagKey(data)
            except AgeError as e:
                raise AgeError('malformed recipient '+quote(text)+': '+str(e))
        if hrp == 'age1tagpq':
            raise AgeError('malformed recipient '+quote(text)+': invalid tagpq recipient public key: invalid public key size')
        if hrp.startswith('age1'):
            return PluginKey(hrp[4:], recipient=text)
        raise AgeError('malformed recipient '+quote(text)+': unexpected HRP: '+quote(hrp))
    if text.startswith('ssh-'):
        from .ssh import parse_authorized_key
        try:
            return parse_authorized_key(text.encode('utf-8','surrogateescape'))
        except AgeError as e:
            raise AgeError('malformed SSH recipient: '+quote(text)+': '+str(e))
    raise AgeError('unknown recipient type: '+quote(text))


def parse_identity(text):
    if text.startswith('AGE-SECRET-KEY-'):
        try:
            hrp,data = bech_decode(text)
        except DecodeError as e:
            raise AgeError('malformed secret key: '+str(e))
        if hrp=='age-secret-key-':
            if len(data)!=32:
                raise AgeError('malformed secret key: invalid X25519 secret key')
            return XKey(secret=data)
        if hrp=='age-secret-key-pq-':
            if len(data)!=32:
                raise AgeError('malformed secret key: invalid MLKEM768-X25519 secret key')
            from .pq import PQKey
            return PQKey(secret=data)
        raise AgeError('malformed secret key: unexpected HRP: '+quote(hrp))
    if text.startswith('AGE-PLUGIN-'):
        try:
            hrp,data = bech_decode(text)
        except DecodeError as e:
            raise AgeError('invalid identity encoding: '+str(e))
        if not hrp.startswith('age-plugin-') or not hrp.endswith('-'):
            raise AgeError('invalid identity HRP: '+quote(hrp))
        return PluginKey(hrp[11:-1], identity=text)
    if text.startswith('age1'):
        raise AgeError('apparent recipient found in identities file')
    raise AgeError('unknown identity type')


def scan_lines(data, label):
    lines = data.split(b'\n')
    if data.endswith(b'\n'):
        lines.pop()
    for index, line in enumerate(lines,1):
        if len(line)>=65536:
            raise AgeError('failed to read '+label+' file: bufio.Scanner: token too long')
        if line.endswith(b'\r'):
            line = line[:-1]
        yield index,line.decode('utf-8','surrogateescape')


def parse_identity_lines(data, name):
    identities = []
    for index,line in scan_lines(data,'identities'):
        if not line or line.startswith('#'):
            continue
        try:
            identities.append(parse_identity(line))
        except AgeError as e:
            raise AgeError('error at line %d: %s'%(index,e))
    if not identities:
        raise AgeError('no identities found')
    return identities


def parse_identity_file(data,name):
    if data.startswith((framing.INTRO,framing.ARMOR_START)):
        return [EncryptedIdentity(data,name)]
    if data.startswith(b'-----BEGIN '):
        from .ssh import parse_private_key
        try:
            return [parse_private_key(data,name)]
        except AgeError as e:
            raise AgeError('malformed SSH identity in '+quote(name)+': '+str(e))
    try:
        return parse_identity_lines(data,name)
    except AgeError as e:
        raise AgeError('failed to read '+quote(name)+': '+str(e))


def parse_recipient_file(data,name,warn):
    recipients = []
    for index,line in scan_lines(data,'recipients'):
        if not line or line.startswith('#'):
            continue
        if line.startswith('AGE-SECRET-KEY-') or line.startswith('AGE-PLUGIN-'):
            raise AgeError(quote(name)+': error at line %d: apparent identity found in recipients file'%index)
        try:
            if not line.startswith('age1'):
                from .ssh import parse_authorized_key, UnsupportedKey
                try:
                    recipient = parse_authorized_key(line.encode('utf-8','surrogateescape'))
                except UnsupportedKey as e:
                    warn('recipients file '+quote(name)+': ignoring unsupported SSH key of type '+quote(e.kind)+' at line '+str(index))
                    continue
            else:
                recipient = parse_recipient(line)
        except AgeError:
            raise AgeError(quote(name)+': malformed recipient at line '+str(index))
        recipients.append(recipient)
    if not recipients:
        raise AgeError(quote(name)+': no recipients found')
    return recipients
