"""Native recipients and identities, and user-specified key files."""
import hashlib
import os
import re
import sys
from .errors import AgeError, quote, os_error
from .primitives import bech_decode, bech_encode, b64encode, b64decode, hkdf, x25519, seal, unseal, DecodeError
from . import format as framing
from .terminal import read_secret

DOMAIN = b'age-encryption.org/v1/'


class XKey:
    pq = False
    def __init__(self, public=None, secret=None):
        self.secret = secret
        self.public = public if public is not None else x25519(secret)

    def wrap(self, key):
        ephemeral = os.urandom(32)
        ephemeral_pub = x25519(ephemeral)
        shared = x25519(ephemeral, self.public)
        if shared == bytes(32):
            raise AgeError('failed to encrypt to X25519 recipient: crypto/ecdh: bad X25519 remote ECDH input: low order point')
        wrapkey = hkdf(shared, ephemeral_pub+self.public, DOMAIN+b'X25519')
        return [('X25519', [b64encode(ephemeral_pub).decode()], seal(wrapkey, key))]

    def unwrap(self, stanzas):
        for kind, args, body in stanzas:
            if kind != 'X25519':
                continue
            if len(args) != 1:
                raise AgeError('invalid X25519 recipient block')
            try:
                ephemeral = b64decode(args[0])
            except DecodeError as e:
                raise AgeError('failed to parse X25519 recipient: '+str(e))
            if len(ephemeral)!=32:
                raise AgeError('invalid X25519 recipient: invalid public key size')
            shared = x25519(self.secret, ephemeral)
            if shared == bytes(32):
                raise AgeError('invalid X25519 recipient: crypto/ecdh: bad X25519 remote ECDH input: low order point')
            wrapkey = hkdf(shared, ephemeral+self.public, DOMAIN+b'X25519')
            key = unseal(wrapkey, body)
            if key is not None:
                if len(key)!=16:
                    raise AgeError('invalid X25519 recipient block')
                return key
        return None


class PluginKey:
    pq = None
    def __init__(self, name, recipient=None, identity=None):
        if not name or re.fullmatch(r'[a-zA-Z0-9_.-]+', name) is None:
            raise AgeError('invalid plugin name: '+quote(name))
        self.name, self.recipient, self.identity = name, recipient, identity

    def _fail(self):
        message = self.name+' plugin: couldn\'t start plugin: '+quote(self.name)+' plugin not found: exec: '+quote('age-plugin-'+self.name)+': executable file not found in $PATH'
        raise AgeError(message, ('you might want to install the '+quote(self.name)+' plugin', 'visit https://age-encryption.org/awesome#plugins for a list of available plugins'))

    def wrap(self, key):
        self._fail()

    def unwrap(self, stanzas):
        self._fail()


class PassphraseKey:
    pq = True
    def __init__(self, passphrase=None):
        self.passphrase = passphrase

    def wrap(self, key):
        salt = os.urandom(16)
        wk = hashlib.scrypt(self.passphrase, salt=DOMAIN+b'scrypt'+salt, n=1<<18, r=8, p=1, maxmem=2147483646, dklen=32)
        return [('scrypt',[b64encode(salt).decode(),'18'],seal(wk,key))]

    def unwrap(self, stanzas):
        if len(stanzas)!=1 or stanzas[0][0]!='scrypt':
            return None
        kind,args,body = stanzas[0]
        if self.passphrase is None:
            try:
                self.passphrase = read_secret('Enter passphrase: ')
            except AgeError as e:
                raise AgeError('could not read passphrase: '+str(e))
        if len(args)!=2:
            raise AgeError('invalid scrypt recipient block')
        try:
            salt = b64decode(args[0])
        except DecodeError as e:
            raise AgeError('failed to parse scrypt salt: '+str(e))
        if len(salt)!=16:
            raise AgeError('invalid scrypt salt')
