STRINGS = {'o':'o','output':'o','r':'r','recipient':'r','R':'R','recipients-file':'R','i':'i','identity':'i','j':'j'}


def parse_flags(argv):
    flags = {'e':False,'d':False,'a':False,'p':False,'version':False,'o':'','r':[],'R':[],'i':[],'j':[], 'identities':[]}
