            if value is None:
                value=True
            elif value in ('1','t','T','TRUE','true','True'):
                value=True
            elif value in ('0','f','F','FALSE','false','False'):
                value=False
            else:
                flag_error('invalid boolean value '+quote(value)+' for -'+name+': parse error')
            flags[BOOLS[name]]=value
        elif name in STRINGS:
            if value is None:
                i+=1
                if i>=len(argv):
                    flag_error('flag needs an argument: -'+name)
                value=argv[i]
            key=STRINGS[name]
            if key=='o':
                flags[key]=value
            else:
                flags[key].append(value)
                if key in ('i','j'):
                    flags['identities'].append((key,value))
        elif name in ('help','h'):
            sys.stderr.write(HELP)
            raise SystemExit(0)
        else:
            flag_error('flag provided but not defined: -'+name)
