REPORT = 'age: report unexpected or unhelpful errors at https://filippo.io/age/report\n'


def warn(message):
    sys.stderr.write('age: warning: '+message+'\n')


def fail(message, hints=()):
    raise AgeError(message,hints)


BOOLS = {'e':'e','encrypt':'e','d':'d','decrypt':'d','a':'a','armor':'a','p':'p','passphrase':'p','version':'version'}
STRINGS = {'o':'o','output':'o','r':'r','recipient':'r','R':'R','recipients-file':'R','i':'i','identity':'i','j':'j'}


def parse_flags(argv):
    flags = {'e':False,'d':False,'a':False,'p':False,'version':False,'o':'','r':[],'R':[],'i':[],'j':[], 'identities':[]}
    i = 0
    while i<len(argv):
        arg=argv[i]
        if len(arg)<2 or arg[0]!='-':
            break
        if arg=='--':
            i+=1
            break
        prefix=2 if arg.startswith('--') else 1
        name=arg[prefix:]
        if not name or name[0] in '-=':
            flag_error('bad flag syntax: '+arg)
        value=None
        if '=' in name:
            name,value=name.split('=',1)
        if name in BOOLS:
            if value is None:
                value=True
            elif value in ('1','t','T','TRUE','true','True'):
                value=True
            elif value in ('0','f','F','FALSE','false','False'):
                value=False
            else:
                flag_error('invalid boolean value '+quote(value)+' for -'+name+': parse error')
            flags[BOOLS[name]]=value
        elif name in STRINGS:
            if value is None:
                i+=1
                if i>=len(argv):
                    flag_error('flag needs an argument: -'+name)
                value=argv[i]
            key=STRINGS[name]
            if key=='o':
                flags[key]=value
            else:
                flags[key].append(value)
                if key in ('i','j'):
                    flags['identities'].append((key,value))
        elif name in ('help','h'):
            sys.stderr.write(HELP)
            raise SystemExit(0)
        else:
            flag_error('flag provided but not defined: -'+name)
        i+=1
    return flags,argv[i:],i


def flag_error(message):
    sys.stderr.write(message+'\n'+HELP)
    raise SystemExit(2)


def validate(f,args,argv,count):
    if len(args)>1:
        message='too many INPUT arguments: '+' '.join(quote(a) for a in args)
        if args[1].startswith('-'):
            # Suggestions preserve flags preceding the first positional argument.
            suggested=[sys.argv[0]]+argv[:count]+args[1:]+args[:1]
            fail(message,('the input file must be specified after all flags','did you mean:','    '+' '.join(shlex.quote(a) for a in suggested)))
        fail(message,('only a single input file may be specified at a time',))
    if f['e'] and f['d']:
        fail("-e/--encrypt can't be used with -d/--decrypt")
    if f['d']:
        if f['a']:
            fail("-a/--armor can't be used with -d/--decrypt",('note that armored files are detected automatically, try again without -a/--armor',))
        if f['p']:
            fail("-p/--passphrase can't be used with -d/--decrypt",('note that password protected files are detected automatically',))
        for name,full in [('r','-r/--recipient'),('R','-R/--recipients-file')]:
            if f[name]:
                fail(full+" can't be used with -d/--decrypt",('did you mean to use -i/--identity to specify a private key?',))
    else:
        if f['identities'] and not f['e']:
            fail("-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt",('did you forget to specify -d/--decrypt?',))
        if f['p']:
            for key,full in [('r','-r/--recipient'),('R','-R/--recipients-file'),('identities','-i/--identity and -j')]:
                if f[key]:
                    fail("-p/--passphrase can't be combined with "+full)
        if not (f['r'] or f['R'] or f['p'] or f['identities']):
            fail('missing recipients',('did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?',))
    for flag,kind in [('r','recipient'),('R','recipients file'),('i','identity file')]:
        seen=set()
        for item in f[flag]:
            if item in seen:
                warn('duplicate '+kind+' '+quote(item))
            seen.add(item)


class InputSource:
    def __init__(self,name):
        self.name=name
        self.error=None
        if name in ('','-'):
            self.fd=0
            self.name='/dev/stdin'
        else:
            try:
                self.fd=os.open(name,os.O_RDONLY)
            except OSError as e:
                fail('failed to open input file '+quote(name)+': '+os_error(e,'open',name))

    def read(self):
        result=[]
        try:
            while True:
                d=os.read(self.fd,1024*1024)
                if not d:break
                result.append(d)
        except OSError as e:
            self.error=os_error(e,'read',self.name)
        return b''.join(result)


class Output:
    def __init__(self,path):
        self.path=path
        self.fd=None
        self.header=False

    def write(self,data):
        if self.fd is None:
            if self.path in ('','-'):
                self.fd=1
            else:
                try:
                    self.fd=os.open(self.path,os.O_WRONLY|os.O_CREAT|os.O_TRUNC,0o666)
                except OSError as e:
                    raise AgeError(os_error(e,'open',self.path))
        try:
            while data:
                n=os.write(self.fd,data)
                data=data[n:]
        except OSError as e:
            raise AgeError(os_error(e,'write',self.path if self.path not in ('','-') else '/dev/stdout'))


class Loader:
    def __init__(self, stdin_used):
        self.stdin_used=stdin_used

    def read(self,path,role):
        if path=='-':
            if self.stdin_used:
                fail('standard input is used for multiple purposes')
            self.stdin_used=True
            return sys.stdin.buffer.read()
        try:
            fd=os.open(path,os.O_RDONLY)
        except OSError as e:
            prefix='failed to open recipient file: ' if role=='recipients' else 'failed to open file: '
            fail(prefix+os_error(e,'open',path))
        try:
            chunks=[]
            try:
                while True:
                    buf=os.read(fd,65536)
                    if not buf:break
                    chunks.append(buf)
            except OSError as e:
                inner='failed to read '+role+' file: '+os_error(e,'read',path)
                if role=='recipients':
                    fail(quote(path)+': '+inner)
                fail('failed to read '+quote(path)+': '+inner)
            return b''.join(chunks)
        finally:
            os.close(fd)

    def identities(self, options):
        identities=[]
        for kind,path in options:
            if kind=='j':
                try:
                    identities.append(keys.PluginKey(path, identity=''))
                except AgeError as e:
                    fail('initializing '+quote(path)+': '+str(e),e.hints)
            else:
                try:
                    data=self.read(path,'identities')
                    identities.extend(keys.parse_identity_file(data,path))
                except AgeError as e:
                    fail('reading '+quote(path)+': '+str(e),e.hints)
        return identities


def encrypt(f,source,loader,output):
    recipients=[]
    for text in f['r']:
        recipients.append(keys.parse_recipient(text))
    for path in f['R']:
        try:
            data=loader.read(path,'recipients')
            recipients.extend(keys.parse_recipient_file(data,path,warn))
        except AgeError as e:
            fail('failed to parse recipient file '+quote(path)+': '+str(e),e.hints)
    recipients.extend(loader.identities(f['identities']))
    if f['p']:
        recipients.append(keys.PassphraseKey(encryption_passphrase()))
    # Resolve encrypted identity files before assembling the recipient list.
    expanded=[]
    for recipient in recipients:
        if isinstance(recipient,keys.EncryptedIdentity):
            try:
                expanded.extend(recipient.load())
            except AgeError as e:
                fail('internal error processing '+quote(recipient.name)+': '+str(e),e.hints)
        else:
            expanded.append(recipient)
    recipients=expanded
    if not f['a'] and not f['o'] and os.isatty(1):
        fail('refusing to output binary to the terminal',('did you mean to use -a/--armor?','force anyway with "-o -"'))
    filekey=os.urandom(16)
    stanzas=[]
    for i,recipient in enumerate(recipients):
        try:
            stanzas.extend(recipient.wrap(filekey))
        except AgeError as e:
            fail('failed to wrap key for recipient #%d: %s'%(i,e),e.hints)
    hdr=framing.make_header(stanzas,filekey)
    # The armor writer retains incomplete base64 lines until more bytes arrive.
    if not f['a']:
        try:
            output.write(hdr)
        except AgeError as e:
            fail('failed to write header: '+str(e))
        data=source.read()
        payload=framing.encrypt_payload(filekey,data)
        output.write(payload)
        if source.error:
            fail(source.error)
    else:
        try:
            output.write(framing.ARMOR_START+b'\n')
        except AgeError as e:
            fail('failed to write header: '+str(e))
        data=source.read()
        allbytes=hdr+framing.encrypt_payload(filekey,data)
        output.write(framing.armor(allbytes)[len(framing.ARMOR_START)+1:])
        if source.error:
            fail(source.error)


def decrypt(f,source,loader,output):
    identities=loader.identities(f['identities'])
    data=source.read()
    stream=framing.dearmor(data,source.error)
    stanzas,mac,header,stream=framing.parse_header(stream)
    passphrase=keys.is_passphrase(stanzas)
    if not identities:
        if not passphrase:
            fail('the file is not passphrase-encrypted, identities are required',('specify identities with -i/--identity or -j to decrypt this file',))
        identities=[keys.PassphraseKey()]
    elif passphrase and all(not isinstance(i,keys.PluginKey) for i in identities):
        fail('file is passphrase-encrypted but identities were specified with -i/--identity or -j',('remove all -i/--identity/-j flags to decrypt passphrase-encrypted files',))
    filekey=keys.find_key(identities,stanzas)
    framing.check_header(filekey,mac,header)
    framing.decrypt_payload(filekey,stream,output.write)


def main(argv=None):
    if argv is None:argv=sys.argv[1:]
    try:
        if not argv:
            sys.stderr.write(HELP)
            return 1
        f,args,count=parse_flags(argv)
        if f['version']:
            print(VERSION)
            return 0
        validate(f,args,argv,count)
        path=args[0] if args else ''
        source=InputSource(path)
        loader=Loader(path in ('','-'))
        output=Output(f['o'])
        if f['d']:
            decrypt(f,source,loader,output)
        else:
            encrypt(f,source,loader,output)
        return 0
    except AgeError as e:
        sys.stderr.write('age: error: '+str(e)+'\n')
        for hint in e.hints:
            sys.stderr.write('age: hint: '+hint+'\n')
        sys.stderr.write(REPORT)
        return 1
    except BrokenPipeError:
        return 1


if __name__=='__main__':
    sys.exit(main())
