"""SSH key encodings and SSH recipient wrapping.

The SSH containers, RSA OAEP, and Edwards-to-Montgomery conversion here are
independent implementations. SSH is a convenience input encoding, not an
external encryption backend.
"""
import base64
import hashlib
import os
import re
import struct
from .errors import AgeError, quote
from .primitives import b64encode, b64decode, hkdf, x25519, seal, unseal, DecodeError

DOMAIN=b'age-encryption.org/v1/'


class UnsupportedKey(AgeError):
    def __init__(self,kind):
        self.kind=kind
        super().__init__('unsupported SSH recipient type: '+quote(kind))


class Reader:
    def __init__(self,data):
        self.data=data
        self.offset=0

    def read(self,n):
        if n<0 or len(self.data)-self.offset<n:
            raise AgeError('ssh: short read')
        data=self.data[self.offset:self.offset+n]
        self.offset+=n
        return data

    def number(self):
        return int.from_bytes(self.read(4),'big')

    def string(self):
        return self.read(self.number())

    def mpi(self):
        return int.from_bytes(self.string(),'big',signed=True)


def ssh_string(data):
    return len(data).to_bytes(4,'big')+data


def ssh_mpi(number):
    data=number.to_bytes((number.bit_length()+7)//8,'big')
    if data and data[0]&128:
        data=b'\0'+data
    return ssh_string(data)


def convert_ed_public(public):
    if len(public)!=32:
        raise AgeError('invalid Ed25519 public key')
    p=2**255-19
    y=int.from_bytes(public,'little')&((1<<255)-1)
    if y>=p:
        raise AgeError('invalid Ed25519 public key')
    x2=(y*y-1)*pow(121665*pow(121666,p-2,p)*y*y+1,p-2,p)%p
    # The conversion uses the Edwards y coordinate, and must reject encodings
    # that do not represent a point on the original curve.
    if x2 and pow(x2,(p-1)//2,p)!=1:
        raise AgeError('invalid Ed25519 public key')
    return ((1+y)*pow(1-y,p-2,p)%p).to_bytes(32,'little')


def mgf1(seed,length):
    return b''.join(hashlib.sha256(seed+i.to_bytes(4,'big')).digest() for i in range((length+31)//32))[:length]


def xor(a,b):
    return bytes(x^y for x,y in zip(a,b))


def oaep_wrap(n,e,message):
    size=(n.bit_length()+7)//8
    label=hashlib.sha256(DOMAIN+b'ssh-rsa').digest()
    db=label+bytes(size-len(message)-66)+b'\1'+message
    seed=os.urandom(32)
    masked_db=xor(db,mgf1(seed,len(db)))
    masked_seed=xor(seed,mgf1(masked_db,32))
    encoded=b'\0'+masked_seed+masked_db
    return pow(int.from_bytes(encoded,'big'),e,n).to_bytes(size,'big')


def oaep_unwrap(n,d,ciphertext):
    size=(n.bit_length()+7)//8
    if len(ciphertext)!=size or int.from_bytes(ciphertext,'big')>=n:
        return None
    encoded=pow(int.from_bytes(ciphertext,'big'),d,n).to_bytes(size,'big')
    if encoded[0]!=0:
        return None
    seed=xor(encoded[1:33],mgf1(encoded[33:],32))
    db=xor(encoded[33:],mgf1(seed,size-33))
    if db[:32]!=hashlib.sha256(DOMAIN+b'ssh-rsa').digest():
        return None
    db=db[32:]
    split=db.find(b'\1')
    if split<0 or db[:split]!=bytes(split):
        return None
    return db[split+1:]


class SSHKey:
    pq=False
    def __init__(self,kind,blob,public,private=None):
        self.kind,self.blob,self.public,self.private=kind,blob,public,private
        self.tag=b64encode(hashlib.sha256(blob).digest()[:4]).decode()
        if kind=='ssh-ed25519':
            self.montgomery=convert_ed_public(public)
            self.tweak=hkdf(b'',blob,DOMAIN+b'ssh-ed25519')
        elif kind=='ssh-rsa':
            n,e=public
            if n.bit_length()<2048:
                raise AgeError('RSA key size is too small: %d bits'%n.bit_length())

    def wrap(self,key):
        if self.kind=='ssh-rsa':
            n,e=self.public
            return [(self.kind,[self.tag],oaep_wrap(n,e,key))]
        secret=os.urandom(32)
        ephemeral=x25519(secret)
        shared=x25519(secret,self.montgomery)
        shared=x25519(self.tweak,shared)
        if shared==bytes(32):
            raise AgeError('failed to encrypt to SSH recipient: bad X25519 remote ECDH input: low order point')
        wk=hkdf(shared,ephemeral+self.montgomery,DOMAIN+b'ssh-ed25519')
        return [(self.kind,[self.tag,b64encode(ephemeral).decode()],seal(wk,key))]

    def unwrap(self,stanzas):
        for kind,args,body in stanzas:
            if kind!=self.kind:
                continue
            expected=1 if kind=='ssh-rsa' else 2
            if len(args)!=expected:
                raise AgeError('invalid '+kind+' recipient block')
            if args[0]!=self.tag:
                continue
            if kind=='ssh-rsa':
                result=oaep_unwrap(self.public[0],self.private,body)
                if result is None:
                    raise AgeError('failed to decrypt file key: crypto/rsa: decryption error')
            else:
                try:
                    ephemeral=b64decode(args[1])
                except DecodeError as e:
                    raise AgeError('failed to parse '+kind+' recipient: '+str(e))
                if len(ephemeral)!=32:
                    raise AgeError('invalid '+kind+' recipient: invalid public key size')
                scalar=hashlib.sha512(self.private[:32]).digest()[:32]
                shared=x25519(self.tweak,x25519(scalar,ephemeral))
                if shared==bytes(32):
                    raise AgeError('invalid '+kind+' recipient: bad X25519 remote ECDH input: low order point')
                wk=hkdf(shared,ephemeral+self.montgomery,DOMAIN+b'ssh-ed25519')
                result=unseal(wk,body)
                if result is None:
                    raise AgeError('failed to decrypt file key: chacha20poly1305: message authentication failed')
            if len(result)!=16:
                raise AgeError('invalid '+kind+' recipient block')
            return result
        return None


def parse_public_blob(blob):
    reader=Reader(blob)
    kind=reader.string().decode('utf-8','surrogateescape')
    if kind=='ssh-ed25519':
        public=reader.string()
        if len(public)!=32:
            raise AgeError('ssh: invalid size %d for Ed25519 public key'%len(public))
        value=public
    elif kind=='ssh-rsa':
        e=reader.mpi()
        n=reader.mpi()
        if e<3 or e%2==0:
            raise AgeError('ssh: incorrect exponent')
        value=(n,e)
    elif kind.startswith('ecdsa-sha2-'):
        curve=reader.string()
        point=reader.string()
        if len(point) not in (65,97,133) or not point.startswith(b'\4'):
            raise AgeError('ssh: invalid elliptic curve point')
        raise UnsupportedKey(kind)
    elif kind=='ssh-dss':
        for i in range(4):reader.mpi()
        raise UnsupportedKey(kind)
    elif kind.startswith('sk-') or kind.endswith('-cert-v01@openssh.com'):
        raise UnsupportedKey(kind)
    else:
        raise AgeError('ssh: unknown key algorithm: '+kind)
    if reader.offset!=len(blob):
        raise AgeError('ssh: trailing junk in public key')
    return SSHKey(kind,blob,value)


def parse_authorized_key(data):
    last=None
    for line in data.splitlines():
        line=line.strip()
        if not line or line.startswith(b'#'):
            continue
        # Locate the algorithm token after an optional authorized_keys option
        # field. Quotes protect spaces inside options.
        fields=re.findall(rb'(?:[^\s"]|"[^"]*")+',line)
        if len(fields)<2:
            continue
        idx=0
        if not fields[0].startswith((b'ssh-',b'ecdsa-',b'sk-')):
            idx=1
        if len(fields)<=idx+1:
            continue
        try:
            blob=b64decode(fields[idx+1],padded=True,strict=False,newlines=True)
            return parse_public_blob(blob)
        except UnsupportedKey:
            raise
        except AgeError as e:
            last=str(e)
        except DecodeError as e:
            last=str(e)
    message='ssh: no key found'
    if last:
        message+='; last parsing error for ignored line: '+last
    raise AgeError(message)


class EncryptedSSHKey:
    pq=False
    def __init__(self,data,name,public):
        self.data,self.name,self.public_key=data,name,public

    def wrap(self,key):
        return self.public_key.wrap(key)

    def unwrap(self,stanzas):
        if not any(t==self.public_key.kind and a and a[0]==self.public_key.tag for t,a,b in stanzas):
            return None
        from .terminal import read_secret
        password=read_secret('Enter passphrase for '+quote(self.name)+': ')
        # OpenSSH's encrypted-key envelope is independent of the age format.
        # A system SSH utility is used only to unlock this optional key input;
        # all file encryption and decryption remains in this codebase.
        import subprocess,tempfile
        fd,path=tempfile.mkstemp(prefix='key-')
        try:
            os.write(fd,self.data)
            os.close(fd)
            p=subprocess.run(['ssh-keygen','-p','-P',password.decode('utf-8','surrogateescape'),'-N','','-f',path],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
            if p.returncode:
                raise AgeError('failed to decrypt SSH key: x509: decryption password incorrect')
            with open(path,'rb') as f:
                identity=parse_private_key(f.read(),self.name)
            return identity.unwrap(stanzas)
        finally:
            os.unlink(path)


def parse_private_key(data,name):
    match=re.search(rb'-----BEGIN ([^-\r\n]+)-----\r?\n(.*?)-----END \1-----',data,re.S)
    if match is None:
        raise AgeError('ssh: no key found')
