#!/usr/bin/env python3
"""Generate the standard Blowfish initial state from the fractional bits of pi.

This is a build step, rather than a checked-in table of unexplained constants.
"""
from decimal import Decimal, localcontext
from pathlib import Path
import sys


def generate(path):
    with localcontext() as ctx:
        ctx.prec = 10120
        a = Decimal(1)
        b = Decimal(1) / Decimal(2).sqrt()
        t = Decimal(1) / 4
        p = Decimal(1)
        for _ in range(15):
            an = (a+b)/2
            b = (a*b).sqrt()
            t -= p*(a-an)**2
            a = an
            p *= 2
        pi = (a+b)**2/(4*t)
        bits = int((pi-3) * Decimal(1 << (32*1042)))
    text = format(bits, '08336x')
    assert text.startswith('243f6a8885a308d313198a2e03707344')
    words = ['0x'+text[i:i+8]+'u' for i in range(0,len(text),8)]
    Path(path).write_text('static const unsigned int pi_state[1042] = {\n'+',\n'.join(', '.join(words[i:i+8]) for i in range(0,len(words),8))+'\n};\n')

if __name__ == '__main__':
    generate(sys.argv[1])
