#include <openssl/blowfish.h>
#include <openssl/sha.h>
#include "pi_state.h"

static uint32_t word(const unsigned char *key, size_t size, size_t *pos) {
    uint32_t w = 0;
    for (int j=0;j<4;j++) {
        w = (w << 8) | key[*pos];
        *pos = (*pos+1) % size;
    }
    return w;
}

static void expand_state(BF_KEY *state, const unsigned char *key,
                         const unsigned char *salt) {
    size_t pos=0, spos=0;
    for (int i=0;i<18;i++) state->P[i] ^= word(key,64,&pos);
    BF_LONG pair[2] = {0,0};
    for (int i=0;i<18;i+=2) {
        if (salt) { pair[0]^=word(salt,64,&spos); pair[1]^=word(salt,64,&spos); }
        BF_encrypt(pair,state);
        state->P[i]=pair[0]; state->P[i+1]=pair[1];
    }
    for (int i=0;i<1024;i+=2) {
        if (salt) { pair[0]^=word(salt,64,&spos); pair[1]^=word(salt,64,&spos); }
        BF_encrypt(pair,state);
        state->S[i]=pair[0]; state->S[i+1]=pair[1];
    }
}

static void bcrypt_core(const unsigned char *pass, const unsigned char *salt,
                        unsigned char result[32]) {
    BF_KEY state;
    memcpy(state.P,pi_state,18*sizeof(uint32_t));
    memcpy(state.S,pi_state+18,1024*sizeof(uint32_t));
    expand_state(&state,pass,salt);
    for (int r=0;r<64;r++) {
        expand_state(&state,salt,NULL);
        expand_state(&state,pass,NULL);
    }
    const unsigned char text[32] = "OxychromaticBlowfishSwatDynamite";
    BF_LONG blocks[8];
    size_t pos=0;
    for (int i=0;i<8;i++) blocks[i]=word(text,32,&pos);
    for (int r=0;r<64;r++) for (int j=0;j<8;j+=2) BF_encrypt(blocks+j,&state);
    for (int i=0;i<8;i++) for (int j=0;j<4;j++) result[i*4+j]=blocks[i]>>(j*8);
    memset(&state,0,sizeof(state));
}

int derive_ssh_key(const unsigned char *pass, size_t passlen,
                   const unsigned char *salt, size_t saltlen, unsigned int rounds,
                   unsigned char *key, size_t keylen) {
    if (!rounds || !keylen || keylen>1024 || !saltlen || saltlen>1048576) return 0;
    unsigned char hp[64],hs[64],temp[32],acc[32];
    unsigned char *saltbuf=malloc(saltlen+4);
    if (!saltbuf) return 0;
    memcpy(saltbuf,salt,saltlen);
    SHA512(pass,passlen,hp);
    size_t stride=(keylen+31)/32;
    size_t amount=(keylen+stride-1)/stride;
    for (size_t count=1;count<=stride;count++) {
        for (int i=0;i<4;i++) saltbuf[saltlen+i]=count>>(24-8*i);
        SHA512(saltbuf,saltlen+4,hs);
        bcrypt_core(hp,hs,temp);
        memcpy(acc,temp,32);
        for (unsigned int r=1;r<rounds;r++) {
            SHA512(temp,32,hs);
            bcrypt_core(hp,hs,temp);
            for (int i=0;i<32;i++) acc[i]^=temp[i];
        }
        for (size_t j=0;j<amount;j++) {
            size_t dest=j*stride+(count-1);
            if (dest<keylen) key[dest]=acc[j];
        }
    }
    free(saltbuf);
    memset(hp,0,sizeof(hp)); memset(temp,0,sizeof(temp)); memset(acc,0,sizeof(acc));
    return 1;
}
